const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Banamepe area along Digul River
  const geometry = ee.Geometry.Rectangle([132.0, -4.5, 133.0, -3.5]);

  // Define date ranges (November ±30 days for better coverage)
  const start2002 = '2002-10-15';
  const end2002 = '2002-11-30';
  const start2019 = '2019-10-15';
  const end2019 = '2019-11-30';

  // Collect Landsat 5 for 2002
  let col2002 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate(start2002, end2002)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  let size2002 = col2002.size().getInfo();
  console.log(`2002 Landsat 5 images: ${size2002}`);

  if (size2002 === 0) {
    console.log('No Landsat 5 data for 2002, attempting fallback.');
    print('C1: Empty Collection');
    return;
  }

  // Collect Landsat 8 for 2019
  let col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate(start2019, end2019)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  let size2019 = col2019.size().getInfo();
  console.log(`2019 Landsat 8 images: ${size2019}`);

  if (size2019 === 0) {
    console.log('No Landsat 8 data for 2019.');
    print('C1: Empty Collection');
    return;
  }

  // Process 2002 image
  const img2002 = col2002.median();
  const ndvi2002 = img2002.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
  const forest2002 = ndvi2002.gte(0.4);

  const count2002 = forest2002.reduceRegion(
    {reducer: ee.Reducer.sum(), geometry: geometry, scale: 1000, maxPixels: 1e9}
  ).get('NDVI').getInfo();

  const total2002 = forest2002.reduceRegion(
    {reducer: ee.Reducer.count(), geometry: geometry, scale: 1000, maxPixels: 1e9}
  ).get('NDVI').getInfo();

  if (total2002 === 0) {
    console.log('No valid pixels for 2002 after masking.');
    print('C2: No Valid Pixels');
    return;
  }

  // Process 2019 image
  const img2019 = col2019.median();
  const ndvi2019 = img2019.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  const forest2019 = ndvi2019.gte(0.4);

  const count2019 = forest2019.reduceRegion(
    {reducer: ee.Reducer.sum(), geometry: geometry, scale: 1000, maxPixels: 1e9}
  ).get('NDVI').getInfo();

  const total2019 = forest2019.reduceRegion(
    {reducer: ee.Reducer.count(), geometry: geometry, scale: 1000, maxPixels: 1e9}
  ).get('NDVI').getInfo();

  if (total2019 === 0) {
    console.log('No valid pixels for 2019 after masking.');
    print('C2: No Valid Pixels');
    return;
  }

  // Calculate forest cover percentages
  const forestPct2002 = (count2002 / total2002) * 100;
  const forestPct2019 = (count2019 / total2019) * 100;

  console.log(`2002 Forest Cover: ${forestPct2002.toFixed(2)}% (${count2002}/${total2002} pixels)`);
  console.log(`2019 Forest Cover: ${forestPct2019.toFixed(2)}% (${count2019}/${total2019} pixels)`);

  // Validate results
  if (isNaN(forestPct2002) || isNaN(forestPct2019)) {
    console.log('Invalid calculation result.');
    print('C3: Calculation Failure');
    return;
  }

  // Determine if forest cover decreased
  if (forestPct2002 > forestPct2019) {
    console.log(`Decrease: ${(forestPct2002 - forestPct2019).toFixed(2)}%`);
    print('A');
  } else {
    console.log(`No decrease (2002: ${forestPct2002.toFixed(2)}% ≤ 2019: ${forestPct2019.toFixed(2)}%)`);
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
